@'
import { Game, emptyInput } from '@ngne/core';
import { stageScene } from './src/scenes/stage.ts';
import { Flight } from './src/components/flight.ts';
import { Bullet, Enemy, Pose } from './src/components/combat.ts';
import { COMBAT } from './src/config/encounters.ts';
const sound = Object.fromEntries(['update','shoot','enemyShot','hit','kill','nova','damage','boss','clear','death'].map(k => [k,()=>{}]));
const moves = [-1,0,1].flatMap(x=>[-1,0,1].map(y=>{const n=Math.max(1,Math.hypot(x,y));return[x/n,y/n]}));
for (const seed of [17,41,83]) {
 const session={settings:{music:0,effects:0,muted:true,reducedMotion:false},screen:'title',best:0,ready:true};
 const game=new Game({seed,state:{best:0,runs:0},transition:(s,c)=>({best:Math.max(s.best,c.score),runs:s.runs+1})});
 let world;
 const original=stageScene(session,{assets:[],sound:()=>sound,take:()=>undefined});
 await game.start(await game.prepare({...original,setup(s){original.setup(s);world=s.world}},{key:'normal-stage'}));
 let move=[0,0],maxBullets=0,bossStart=null,novas=0;
 for(let tick=0;tick<18000;tick++) {
  const run=session.run;
  if(run.phase==='clear'||run.phase==='dead')break;
  if(run.phase==='boss'&&bossStart===null)bossStart=run.seconds;
  const shots=[];world.query(Pose,Bullet).eachChunk(({views:v,count})=>{for(let i=0;i<count;i++)if(v.bullet.team[i]&&v.bullet.active[i])shots.push({x:v.pose.x[i],y:v.pose.y[i],vx:v.bullet.vx[i],vy:v.bullet.vy[i],r:6.5})});
  maxBullets=Math.max(maxBullets,shots.length);
  let vx=0,vy=0;world.query(Flight).eachChunk(({views:v})=>{vx=v.flight.vx[0];vy=v.flight.vy[0]});
  if(tick%6===0) {
   const threats=[...shots];
   world.query(Pose,Enemy).eachChunk(({views:v,count})=>{for(let i=0;i<count;i++)if(v.enemy.active[i])threats.push({x:v.pose.x[i],y:v.pose.y[i],vx:(v.pose.x[i]-v.pose.px[i])*60,vy:(v.pose.y[i]-v.pose.py[i])*60,r:v.enemy.radius[i]+4})});
   let best=Infinity;
   for(const candidate of moves) {
    let x=run.x,y=run.y,dx=vx,dy=vy,cost=0;
    for(let step=1;step<=8;step++) {
     for(const [axis,input] of candidate.entries()) {
      const response=input===0?8:14,target=input*135;
      if(axis===0)dx=target+(dx-target)*Math.exp(-response*.1);else dy=target+(dy-target)*Math.exp(-response*.1);
     }
     x=Math.max(18,Math.min(462,x+dx*.1));y=Math.max(43,Math.min(239,y+dy*.1));
     const t=step*.1;
     for(const b of threats){const d=Math.hypot(x-b.x-b.vx*t,y-b.y-b.vy*t)-b.r;cost+=(d<1?2000:200*Math.exp(-d*d/180))/(step*.15+1)}
     cost+=(y-196)**2*.0004+(x-240)**2*.00001;
    }
    cost+=Math.hypot(candidate[0]-move[0],candidate[1]-move[1])*.08;
    if(cost<best){best=cost;move=candidate}
   }
  }
  const near=shots.some(b=>Math.hypot(run.x-b.x,run.y-b.y)<36);
  const nova=run.nova>=.999&&(near||shots.length>35||(run.phase==='boss'&&run.bossHealth<60));
  if(nova)novas++;
  game.tick({...emptyInput(),axes:move,pressed:nova?['Space']:[]});
 }
 console.log(JSON.stringify({seed,bossHp:COMBAT.bossHp,outcome:session.run.phase,seconds:+session.run.seconds.toFixed(2),hull:session.run.hull,kills:session.run.kills,score:session.run.score,bossHealth:session.run.bossHealth,bossStart,maxBullets,novas}));
 game.dispose();
}
